/// <summary>
/// CB201_RebatesExtension_GSTchanges
/// TAMRebateCreateDocumentFinancial extension to handles the item sales tax information
/// </summary>
[ExtensionOf(classStr(TAMRebateCreateDocumentFinancial))]
final class METTAMRebateCreateDocumentFinancial_Extension
{
    private TaxItemGroup itemSalesTaxGroup;
    private Description itemTypeDescription;
    private CustAccount metRebateRefAccount;

}

Method.Source:
/// <summary>
/// CB201_RebatesExtension_GSTchanges
/// Get or set item sales tax group from source transactions
/// </summary>
/// <param name = "_itemSalesTaxGroup">TaxItemGroup of source transactions</param>
/// <returns>TaxItemGroup</returns>
public TaxItemGroup parmItemSalesTaxGroup(TaxItemGroup _itemSalesTaxGroup = itemSalesTaxGroup)
{
    itemSalesTaxGroup = _itemSalesTaxGroup;

    return itemSalesTaxGroup;
}

/// <summary>
/// CB272_Salesinvoice
/// Get or set Item Type description from source transactions
/// </summary>
/// <param name = "_itemTypeDescription">Itemtype description of source transactions</param>
/// <returns>Description</returns>
public Description parmItemTypeDescription(Description _itemTypeDescription = itemTypeDescription)
{
    itemTypeDescription = _itemTypeDescription;

    return itemTypeDescription;
}

/// <summary>
/// Gets or sets the custom rebate reference account used for Free Text Invoice header splitting
/// </summary>
/// <param name = "_metRebateRefAccount">Customer Account</param>
/// <returns>Customer Account</returns>
public CustAccount parmMetRebateRefAccount(CustAccount _metRebateRefAccount = metRebateRefAccount)
{
    metRebateRefAccount = _metRebateRefAccount;

    return metRebateRefAccount;
}
